<?php
require 'config.php';require 'includes/functions.php';need_role(['admin','hospital']);verify();
$hospital=null;if(user()['role']==='hospital'){$q=$pdo->prepare("SELECT * FROM hospitals WHERE user_id=?");$q->execute([user()['id']]);$hospital=$q->fetch();if(!$hospital)exit('Hospital profile missing.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(isset($_POST['update_hospital'])&&$hospital){$q=$pdo->prepare("UPDATE hospitals SET name=?,address=?,city=?,latitude=?,longitude=? WHERE id=?");$q->execute([trim($_POST['name']),trim($_POST['address']),trim($_POST['city']),$_POST['lat']?:null,$_POST['lng']?:null,$hospital['id']]);flash('Hospital profile updated.');go('manage.php');}
 if(isset($_POST['status'])){$st=$_POST['status'];if(in_array($st,['pending','confirmed','completed','cancelled'],true)){$sql="UPDATE appointments SET status=? WHERE id=?";$args=[$st,(int)$_POST['id']];if($hospital){$sql.=" AND doctor_id IN (SELECT id FROM doctors WHERE hospital_id=?)";$args[]=$hospital['id'];}$pdo->prepare($sql)->execute($args);flash('Appointment status updated.');}go('manage.php');}
 if(isset($_POST['add_doctor'])&&$hospital){try{$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'doctor')");$q->execute([trim($_POST['doctor']),strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO doctors(user_id,hospital_id,specialty,consultation_fee) VALUES(?,?,?,?)");$q->execute([$uid,$hospital['id'],trim($_POST['specialty']),max(0,(float)$_POST['fee'])]);$pdo->commit();flash('Doctor added.');}catch(Throwable $e){$pdo->rollBack();flash('Could not add doctor; check email uniqueness.','error');}go('manage.php');}
}
$where=$hospital?'WHERE d.hospital_id='.(int)$hospital['id']:'';$sql="SELECT a.*,p.name patient,d.specialty,du.name doctor,h.name hospital FROM appointments a JOIN users p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id JOIN users du ON du.id=d.user_id JOIN hospitals h ON h.id=d.hospital_id $where ORDER BY a.appointment_date DESC,a.appointment_time DESC";$appointments=$pdo->query($sql)->fetchAll();
$title='Management';require 'includes/header.php';?>
<div class="intro"><span class="tag">MANAGEMENT CONSOLE</span><h1>Appointment management</h1><p>Manage appointments and view operational statistics.</p></div><div class="stats"><div class="stat"><b><?=$pdo->query("SELECT COUNT(*) FROM appointments")->fetchColumn()?></b><span>Total appointments</span></div><div class="stat"><b><?=$pdo->query("SELECT COUNT(*) FROM appointments WHERE status='pending'")->fetchColumn()?></b><span>Pending</span></div><div class="stat"><b><?=number_format((float)$pdo->query("SELECT AVG(rating) FROM reviews")->fetchColumn(),1)?> ★</b><span>Average doctor rating</span></div></div>
<?php if($hospital):?><section class="panel"><h2>Hospital details and location</h2><form method="post"><?=csrf()?><label>Hospital name<input name="name" value="<?=e($hospital['name'])?>" required></label><label>Address<input name="address" value="<?=e($hospital['address'])?>"></label><div class="two"><label>City<input name="city" value="<?=e($hospital['city'])?>"></label><label>Latitude<input name="lat" value="<?=e($hospital['latitude'])?>"></label><label>Longitude<input name="lng" value="<?=e($hospital['longitude'])?>"></label></div><button class="btn" name="update_hospital">Update hospital</button></form><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=<?=urlencode($hospital['address'].' '.$hospital['city'])?>">View location on Google Maps ↗</a></section>
<section class="panel"><h2>Add doctor</h2><form method="post"><?=csrf()?><div class="two"><label>Doctor name<input name="doctor" required></label><label>Doctor email<input type="email" name="email" required></label><label>Specialty<input name="specialty" required placeholder="Cardiology"></label><label>Consultation fee<input type="number" name="fee" min="0" step="0.01" required></label><label>Temporary password<input type="password" name="password" minlength="8" required></label></div><button class="btn" name="add_doctor">Add doctor</button></form></section><?php endif;?>
<section class="panel"><h2>Appointments</h2><div class="tablewrap"><table><tr><th>Patient</th><th>Doctor / hospital</th><th>Date / time</th><th>Reason</th><th>Status</th><th>Update</th></tr><?php foreach($appointments as $a):?><tr><td><?=e($a['patient'])?></td><td>Dr. <?=e($a['doctor'])?><br><?=e($a['specialty'])?><br><small><?=e($a['hospital'])?></small></td><td><?=e($a['appointment_date'])?> <?=e(substr($a['appointment_time'],0,5))?></td><td><?=e($a['reason'])?></td><td><?=e($a['status'])?></td><td><form method="post"><?=csrf()?><input type="hidden" name="id" value="<?=$a['id']?>"><select name="status"><?php foreach(['pending','confirmed','completed','cancelled'] as $s):?><option <?=$a['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn tiny">Save</button></form></td></tr><?php endforeach;?></table></div></section>
<?php require 'includes/footer.php';?>